/* @lc app=leetcode id=1649 lang=kotlin */ class Solution { fun createSortedArray(instructions: IntArray): Int = IntArray(100005).let { bit -> instructions.indices.fold(0L) { ans, total -> instructions[total].let { x -> generateSequence(x - 1) { idx -> (idx - (idx and -idx)).takeIf { it > 0 } }.sumOf { idx -> bit[idx] }.let { less -> generateSequence(x) { idx -> (idx - (idx and -idx)).takeIf { it > 0 } }.sumOf { idx -> bit[idx] }.let { lessOrEqual -> (total - lessOrEqual).let { greater -> generateSequence(x) { idx -> (idx + (idx and -idx)).takeIf { it <= 100000 } }.forEach { idx -> bit[idx]++ }.let { (ans + minOf(less, greater)) % 1000000007 } } } } } }.toInt() } }